Review only this complete patch. Requirement: add a pure helper that converts already-validated ASCII tag labels into lowercase hyphenated slugs, trimming leading and trailing whitespace and collapsing runs of spaces, underscores, and hyphens. Empty output is allowed and callers validate it. Do not edit files or invent broader requirements.

```diff
--- /dev/null
+++ b/src/slug.ts
@@ -0,0 +1,4 @@
+export function toTagSlug(label: string): string {
+  return label.trim().toLowerCase().replace(/[ _-]+/g, '-');
+}
+
--- /dev/null
+++ b/src/slug.test.ts
@@ -0,0 +1,9 @@
+import { toTagSlug } from './slug';
+
+it.each([
+  ['Release Notes', 'release-notes'],
+  ['  API_v2  ', 'api-v2'],
+  ['one---two', 'one-two'],
+  ['', ''],
+])('slugifies %p', (input, expected) => {
